-- Generated by datagen/gen.py from Keira3, the Personal Spell Editor, the HoT Spell Editor
-- data and the HoT core headers. Do not edit by hand, re-run the generator instead.
GameEditorData = GameEditorData or {}

-- Enums[name][value] = label. EnumTooltips[name][value] = longer text where a source had one.
-- Flags[name] = { {bit = 0..63, name, tooltip, alias, const}, ... } sorted by bit.
-- MiscValue.Effect / MiscValue.Aura describe EffectMiscValue (a) and EffectMiscValueB (b).
-- ClassMask[familyId][bit 0..95] = name of the spells that carry that SpellFamilyFlags bit.

GameEditorData.Enums = GameEditorData.Enums or {}
GameEditorData.EnumTooltips = GameEditorData.EnumTooltips or {}
GameEditorData.Flags = GameEditorData.Flags or {}
GameEditorData.MiscValue = GameEditorData.MiscValue or {}
GameEditorData.ClassMask = GameEditorData.ClassMask or {}

